  <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>

  <script type="text/babel">
    const ContactForm = () => {
      const [errors, setErrors] = React.useState({});
      const nameRef = React.useRef(null);
      const emailRef = React.useRef(null);

      const handleSubmit = (e) => {
        e.preventDefault();

        const formData = new FormData(e.target);
        const name = formData.get('name').trim();
        const email = formData.get('email').trim();

        const newErrors = {};

        if (!name) {
          newErrors.name = "Error: Full name is required.";
        }

        if (!email) {
          newErrors.email = "Error: Email address is required.";
        } else if (!/^\S+@\S+\.\S+$/.test(email)) {
          newErrors.email = "Error: Enter a valid email address.";
        }

        setErrors(newErrors);

        if (Object.keys(newErrors).length > 0) {
          if (newErrors.name && nameRef.current) {
            nameRef.current.focus();
          } else if (newErrors.email && emailRef.current) {
            emailRef.current.focus();
          }
        } else {
          // Success case
          alert("Support request submitted!");
          e.target.reset();
          setErrors({});
        }
      };

      return (
        <form noValidate onSubmit={handleSubmit}>
          <p className="required-legend">
            <span aria-hidden="true" className="required-marker">*</span> Indicates required field
          </p>

          <div className="form-field">
            <label htmlFor="name">
              Full name <span aria-hidden="true" className="required-marker">*</span>
            </label>
            <input 
              id="name" 
              name="name" 
              type="text" 
              required 
              autoComplete="name"
              aria-invalid={!!errors.name}
              aria-describedby={errors.name ? "name-error" : undefined}
              ref={nameRef}
            />
            {errors.name && <p id="name-error" className="error-text">{errors.name}</p>}
          </div>

          <div className="form-field">
            <label htmlFor="email">
              Email address <span aria-hidden="true" className="required-marker">*</span>
            </label>
            <input 
              id="email" 
              name="email" 
              type="email" 
              required 
              autoComplete="email"
              aria-invalid={!!errors.email}
              aria-describedby={errors.email ? "email-error" : undefined}
              ref={emailRef}
            />
            {errors.email && <p id="email-error" className="error-text">{errors.email}</p>}
          </div>

          <div className="form-field">
            <label htmlFor="phone">Phone number</label>
            <input 
              id="phone" 
              name="phone" 
              type="tel" 
              autoComplete="tel"
              aria-describedby="phone-help"
            />
            <p id="phone-help" className="help-text">Format: +1 (555) 000-0000</p>
          </div>

          <button type="submit">Submit Request</button>
        </form>
      );
    };

    const App = () => (
      <main>
        <h1>Support Contact</h1>
        <ContactForm />
      </main>
    );

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<App />);
  </script>
</body>
